package xyz.shuncongci.leica

import org.junit.Assert.*
import org.junit.Test
import java.io.*
import java.nio.file.Files
import java.util.concurrent.CancellationException
import kotlin.math.*
import xyz.shuncongci.leica.LegendaryMath.Frame

class HdrOutputColorTest {
    private fun base(w:Int=19,h:Int=33)=Planes(w,h).also{p->for(c in 0..2)for(i in 0 until p.size)p.plane(c)[i]=(20+(i*17+c*47)%230).toByte()}
    private fun radiance(p:Planes)=Frame(p.width,p.height,3,FloatArray(p.size*3){i->HdrMath.linearByte(p.plane(i/p.size)[i%p.size].toInt()and 255)*(1.2f+(i%11)*.07f)})
    private fun collect(p:HdrPixels):Frame {val f=Frame(p.w,p.h,3,FloatArray(p.w*p.h*3));val row=FloatArray(p.w);for(c in 0..2)for(y in 0 until p.h){p.read(c,y,1,row,Cancel());row.copyInto(f.data,c*f.size+y*p.w)};return f}
    private fun bits(a:FloatArray,b:FloatArray){assertArrayEquals(a.map{it.toRawBits()}.toIntArray(),b.map{it.toRawBits()}.toIntArray())}
    private fun make(p:Planes)=HdrOutputColor.apply(p,HdrPixels.of(radiance(p)),Cancel())
    private fun <T> disk(body:(File)->T):T {val d=Files.createTempDirectory("hdr-output-color").toFile();try{return body(d)}finally{check(d.deleteRecursively())}}
    private fun pixel(s:DoubleArray,h:DoubleArray,d:Double=4.0):DoubleArray=DoubleArray(3).also{HdrOutputColor.transform(s,h,d,it,DoubleArray(12))}
    private fun Y(a:DoubleArray)=.2126*a[0]+.7152*a[1]+.0722*a[2]
    private fun lab(a:DoubleArray):DoubleArray {val l=Math.cbrt(.4122214708*a[0]+.5363325363*a[1]+.0514459929*a[2]);val m=Math.cbrt(.2119034982*a[0]+.6806995451*a[1]+.1073969566*a[2]);val s=Math.cbrt(.0883024619*a[0]+.2817188376*a[1]+.6299787005*a[2]);return doubleArrayOf(.2104542553*l+.7936177850*m-.0040720468*s,1.9779984951*l-2.4285922050*m+.4505937099*s,.0259040371*l+.7827717662*m-.8086757660*s)}
    private fun sat(a:DoubleArray):Double {val z=lab(a);return hypot(z[1],z[2])/z[0]}
    @Test fun numpyStudyOracleMatchesScalarProduction(){var n=0;javaClass.getResourceAsStream("/hdr-output-color.csv")!!.bufferedReader().useLines{lines->lines.filter{!it.startsWith("#") && it.isNotBlank()}.forEach{line->val a=line.split(',').map{it.toDouble()};val out=pixel(a.take(3).toDoubleArray(),a.drop(3).take(3).toDoubleArray(),a[6]);for(c in 0..2)assertEquals("sample $n channel $c",a[7+c],out[c],3e-12);n++}};assertEquals(784,n)}
    @Test fun neutralHighlightsBecomeBrighterWithoutTint(){val h=doubleArrayOf(1.5,1.5,1.5);val o=pixel(doubleArrayOf(.7,.7,.7),h);assertTrue(o[0]>h[0]);assertEquals(o[0],o[1],1e-14);assertEquals(o[1],o[2],1e-14)}
    @Test fun brightColourGetsBothLuminanceAndRelativeChroma(){val h=doubleArrayOf(1.4,1.0,.7);val o=pixel(doubleArrayOf(.7,.5,.3),h);assertTrue(Y(o)>Y(h));assertTrue(sat(o)>sat(h));val a=lab(h);val b=lab(o);assertEquals(atan2(a[2],a[1]),atan2(b[2],b[1]),2e-13)}
    @Test fun darkGateLeavesAllEndpointBitsUntouched(){val h=doubleArrayOf(.03,.001,0.0);assertArrayEquals(h,pixel(doubleArrayOf(.01,.01,.01),h),0.0)}
    @Test fun pureBlackIsNotLifted(){assertArrayEquals(DoubleArray(3),pixel(DoubleArray(3),DoubleArray(3)),0.0)}
    @Test fun zeroRadianceIsNotInventedForBrightSdr(){assertArrayEquals(DoubleArray(3),pixel(doubleArrayOf(1.0,1.0,1.0),DoubleArray(3)),0.0)}
    @Test fun alreadyAtCapacityIsNotHardClipped(){val h=doubleArrayOf(4.0,4.0,4.0);assertArrayEquals(h,pixel(doubleArrayOf(1.0,1.0,1.0),h),0.0)}
    @Test fun arbitraryBaselineBeyondBudgetIsPreservedNotDimmed(){val h=doubleArrayOf(8.0,1.0,2.0);assertArrayEquals(h,pixel(doubleArrayOf(.8,.4,.4),h),0.0)}
    @Test fun purePrimaryStaysNonnegativeAndFinite(){val o=pixel(doubleArrayOf(.8,0.0,0.0),doubleArrayOf(1.4,0.0,0.0));assertTrue(o.all{it.isFinite() && it>=0});assertTrue(o[0]>=1.4)}
    @Test fun syntheticPartialHeadroomBoundsForModifiedPixels(){val random=java.util.Random(28684);repeat(400){val s=DoubleArray(3){.13+random.nextDouble()*.87};val h=DoubleArray(3){.05+random.nextDouble()*2.9};val o=pixel(s,h);for(c in 0..2)if(o[c]!=h[c])for(step in 0..100){val H=4.0.pow(step/100.0);val w=ln(H)/ln(4.0);val value=max(0.0,(s[c]+1.0/64)*((o[c]+1.0/64)/(s[c]+1.0/64)).pow(w)-1.0/64);assertTrue("$value > $H",value<=H+1e-12)}}}
    @Test fun scalarInvalidRadianceRejected(){for(v in listOf(-1.0,Double.NaN,Double.POSITIVE_INFINITY,65505.0))assertThrows(IllegalArgumentException::class.java){pixel(doubleArrayOf(.5,.5,.5),doubleArrayOf(v,1.0,1.0))}}
    @Test fun scalarInvalidSdrRejected(){for(v in listOf(-.1,1.01,Double.NaN))assertThrows(IllegalArgumentException::class.java){pixel(doubleArrayOf(v,.5,.5),doubleArrayOf(1.0,1.0,1.0))}}
    @Test fun dimensionsAndSourcePixelsStayExact(){val p=base();val f=radiance(p);val original=f.data.copyOf();val before=Array(3){p.plane(it).copyOf()};val out=HdrOutputColor.apply(p,HdrPixels.of(f),Cancel());assertEquals(p.width,out.w);assertEquals(p.height,out.h);collect(out);bits(original,f.data);for(c in 0..2)assertArrayEquals(before[c],p.plane(c))}
    @Test fun repeatedReadsAreDeterministic(){val p=make(base());val first=collect(p);repeat(3){bits(first.data,collect(p).data)}}
    @Test fun repeatedWrappingDoesNotAccumulate(){val p=base();val f=make(p);assertSame(f,HdrOutputColor.apply(p,f,Cancel()));assertSame(f,HdrOutputBrightness.apply(f))}
    @Test fun requestSpanningStripBoundariesMatchesSingleRows(){val p=make(base());val f=collect(p);val out=FloatArray(p.w*29);for(c in 0..2){p.read(c,3,29,out,Cancel());bits(f.data.copyOfRange(c*f.size+3*p.w,c*f.size+32*p.w),out)}}
    @Test fun scratchTailStaysUntouched(){val p=make(base());val out=FloatArray(p.w+7){-19f};p.read(1,12,1,out,Cancel());assertTrue(out.takeLast(7).all{it==-19f})}
    @Test fun outOfOrderChannelsAndStripsStayDeterministic(){val p=make(base());val f=collect(p);val a=FloatArray(p.w);for(y in listOf(32,0,17,15,31,16,0))for(c in listOf(2,0,1)){p.read(c,y,1,a,Cancel());bits(f.data.copyOfRange(c*f.size+y*p.w,c*f.size+(y+1)*p.w),a)}}
    @Test fun invalidReadRangesRejected(){val p=make(base());for(call in listOf<()->Unit>({p.read(3,0,1,FloatArray(p.w),Cancel())},{p.read(0,-1,1,FloatArray(p.w),Cancel())},{p.read(0,0,0,FloatArray(p.w),Cancel())},{p.read(0,p.h-1,2,FloatArray(p.w*2),Cancel())},{p.read(0,0,1,FloatArray(p.w-1),Cancel())}))assertThrows(IllegalArgumentException::class.java){call()}}
    @Test fun cancellationBeforeCapacityScanDoesNotRead(){var calls=0;val p=base();assertThrows(CancellationException::class.java){HdrOutputColor.apply(HdrPixels.of(radiance(p)),Cancel().apply{cancelled=true}){_,_,_->calls++}};assertEquals(0,calls)}
    @Test fun cancellationDuringCapacityScanIsNotIgnored(){val p=base();val cancel=Cancel();assertThrows(CancellationException::class.java){HdrOutputColor.apply(HdrPixels.of(radiance(p)),cancel){y,r,a->p.toArgbRows(y,r,a);cancel.cancelled=true}}}
    @Test fun cancellationOnCachedReadIsStillChecked(){val p=make(base());p.read(0,0,1,FloatArray(p.w),Cancel());assertThrows(CancellationException::class.java){p.read(1,0,1,FloatArray(p.w),Cancel().apply{cancelled=true})}}
    @Test fun realIoErrorsAreNotSwallowed(){val marker=IOException("synthetic");val p=base();val e=assertThrows(IOException::class.java){HdrOutputColor.apply(HdrPixels.of(radiance(p)),Cancel()){_,_,_->throw marker}};assertSame(marker,e);assertFalse(HdrAutoPolicy.canFallback(e))}
    @Test fun capacityEqualsUnenhancedEncoderBudget(){val p=base();val f=radiance(p);assertEquals(HdrMath.encode(p,f,Cancel()).display.toRawBits(),checkNotNull(HdrOutputColor.apply(p,HdrPixels.of(f),Cancel()).displayCapacity).toRawBits())}
    @Test fun suppliedJpegDecodedBaseIsActuallyUsed(){val p=base();val f=radiance(p);val altered=Planes(p.width,p.height).also{for(c in 0..2)it.plane(c).fill(20)};var reads=0;val a=HdrOutputColor.apply(HdrPixels.of(f),Cancel()){y,r,out->reads++;altered.toArgbRows(y,r,out)};val b=HdrOutputColor.apply(altered,HdrPixels.of(f),Cancel());bits(collect(a).data,collect(b).data);assertEquals(a.displayCapacity,b.displayCapacity);assertTrue(reads>0)}
    @Test fun encodeUsesFrozenBudgetNotNewExtrema(){val p=base();val f=make(p);val m=HdrMath.encodePixelRows(f,Cancel(),{y,r,a->p.toArgbRows(y,r,a)},{_,_,_->});assertEquals(f.displayCapacity!!.toRawBits(),m.display.toRawBits())}
    @Test fun hdr2RoundTripPreservesBudgetAndFloatBits()=disk{d->val p=base();val h=make(p);val expected=collect(h);val f=File(d,"pair");HdrResultStore.write(f,p,h,Cancel());assertEquals(16L+15L*p.size,f.length());HdrResultStore.readRows(f,p.width,p.height,Cancel()).let{(s,r)->r.use{assertEquals(h.displayCapacity,it.displayCapacity);bits(expected.data,collect(it).data);for(c in 0..2)assertArrayEquals(p.plane(c),s.plane(c))}}}
    @Test fun hdr2RepeatedSaveIsByteExact()=disk{d->val p=base();val f=File(d,"pair");HdrResultStore.write(f,p,make(p),Cancel());repeat(3){i->val (s,h)=HdrResultStore.readRows(f,p.width,p.height,Cancel());h.use{assertSame(it,HdrOutputColor.apply(s,it,Cancel()));val out=File(d,"save$i");HdrResultStore.write(out,s,it,Cancel());assertArrayEquals(f.readBytes(),out.readBytes())}}}
    @Test fun hdr1LegacyReadAndSaveRemainByteExact()=disk{d->val p=base();val f=File(d,"pair");HdrResultStore.write(f,p,radiance(p),Cancel());val before=f.readBytes();HdrResultStore.readRows(f,p.width,p.height,Cancel()).let{(s,h)->h.use{assertNull(it.displayCapacity);val out=File(d,"copy");HdrResultStore.write(out,s,it,Cancel());assertArrayEquals(before,out.readBytes())}}}
    @Test fun cropAndResizeKeepBudgetWithoutAnotherEnhancement()=disk{d->val p=base(24,18);val h=make(p);val expected=collect(h);val f=File(d,"pair");HdrResultStore.write(f,p,h,Cancel());HdrResultStore.readRows(f,p.width,p.height,Cancel()).second.use{r->val crop=CompositionGeometry.Crop(.25,0.0,.75,1.0);val a=HdrPixelGeometry.crop(r,crop,6,9);assertEquals(h.displayCapacity,a.displayCapacity);bits(HdrMath.geometry(expected,crop,6,9,Cancel()).data,collect(a).data)}}
    @Test fun rawCheckpointCannotSilentlyLoseFinishedBudget()=disk{d->val f=File(d,"raw");assertThrows(IllegalArgumentException::class.java){HdrFloatFile.write(f,make(base()),Cancel())};assertFalse(f.exists())}
    @Test fun malformedHdr2BudgetRejected()=disk{d->val p=base();val f=File(d,"pair");HdrResultStore.write(f,p,make(p),Cancel());for(v in listOf(0f,1f,Float.NaN,Float.POSITIVE_INFINITY)){RandomAccessFile(f,"rw").use{it.seek(12);it.writeFloat(v)};assertThrows(IllegalArgumentException::class.java){HdrResultStore.readRows(f,p.width,p.height,Cancel())}}}
    @Test fun truncatedHdr2Rejected():Unit=disk{d->val p=base();val f=File(d,"pair");HdrResultStore.write(f,p,make(p),Cancel());RandomAccessFile(f,"rw").use{it.setLength(f.length()-1)};assertThrows(IllegalStateException::class.java){HdrResultStore.readRows(f,p.width,p.height,Cancel())}}
    @Test fun hdr2CancelWriteCleansPartial()=disk{d->val p=base();val h=make(p);val f=File(d,"pair");assertThrows(CancellationException::class.java){HdrResultStore.write(f,p,h,Cancel().apply{cancelled=true})};assertFalse(f.exists())}
    @Test fun newHdrIdentityLeavesSdrIdentityAlone(){val old=HdrOutputBrightness.renderKey("scene",true);assertNotEquals(old,HdrOutputColor.renderKey(old,true));assertEquals("scene",HdrOutputColor.renderKey("scene",false))}
    @Test fun staleRawCacheInvalidatedButFinishedResultRetained()=disk{d->val s=EditSession(d);s.importSource(File(d,"original").apply{writeText("source")});val old=HdrOutputBrightness.renderKey("scene",true);s.beginRender(old);s.store.update(blobs=mapOf("render.hdr" to {it.writeText("raw")},"result" to {it.writeText("last")},"result-pair" to {it.writeText("pair")},"result-jpeg" to {it.writeText("jpeg")}));s.beginRender(HdrOutputColor.renderKey(old,true));assertNull(s.store.file("render.hdr"));assertEquals("source",s.source()!!.readText());assertEquals("last",s.store.file("result")!!.readText());assertEquals("pair",s.store.file("result-pair")!!.readText());assertEquals("jpeg",s.store.file("result-jpeg")!!.readText())}
    @Test fun resumedRawCheckpointIsNotRewritten()=disk{d->val p=base();val f=File(d,"raw");HdrFloatFile.write(f,HdrPixels.of(radiance(p)),Cancel());val bytes=f.readBytes();var first:FloatArray?=null;repeat(2){HdrFloatFile.open(f).use{val h=HdrOutputColor.apply(p,HdrOutputBrightness.apply(it),Cancel());val actual=collect(h).data;if(first==null)first=actual else bits(first!!,actual)}};assertArrayEquals(bytes,f.readBytes())}
    @Test fun hdr2NumericCompatibilityReturnsSameRadiance()=disk{d->val p=base();val h=make(p);val expected=collect(h);val f=File(d,"pair");HdrResultStore.write(f,p,h,Cancel());bits(expected.data,HdrResultStore.read(f,p.width,p.height,Cancel()).second.data)}
    @Test fun enhancedRowsRemainBoundedForTallVirtualSource(){var maximumRows=0;var reads=0;val p=object:HdrPixels{override val w=7;override val h=2003;override fun read(channel:Int,y:Int,rows:Int,values:FloatArray,cancel:Cancel){maximumRows=max(maximumRows,rows);reads++;values.fill(1.5f,0,w*rows)}};val made=HdrOutputColor.apply(p,Cancel()){_,r,a->a.fill(0xffbbbbbb.toInt(),0,r*p.w)};val count=reads;made.read(2,999,3,FloatArray(21),Cancel());assertTrue(maximumRows<=16);assertTrue(reads-count<=6)}
}
